export function StudioUseEvidence({ record, onOpenTask, onReadSource }: { record: StudioUseRecord; onOpenTask: (projectId: string, taskId: string) => void; onReadSource: (ref: StudioSourceRef) => void }) {
  const latest = record.assessments?.at(-1);
  const originalStatus = record.verification === 'not_assessed' ? '专业质量未评定' : record.verification === 'pass' ? '原使用核对通过' : record.verification === 'fail' ? '原使用核对未通过' : '原核对结果未知';
  return <article className="studio-usage"><button type="button" className="text-button" onClick={() => onOpenTask(record.projectId, record.taskId)}>{record.report.title || '打开原分析任务'}</button>
    <p className="studio-meta">{time(record.createdAt)}{record.graphSnapshotId ? ` · 固定图 ${record.graphSnapshotId}` : ''}</p>
    {latest ? <section className="studio-assessment" aria-label="最新作者使用评估"><h4>最新作者评估 · {latest.status === 'pass' ? '相应范围通过' : latest.status === 'fail' ? '相应范围未通过' : '相应范围未知'}</h4><p>{latest.result}</p><p className="studio-meta">{time(latest.at)} · 这是作者对所列报告和来源范围的评估，不是独立专业评分或整套体系验收。</p><SourceList sources={[latest.report, ...latest.sources]} open={onReadSource} /></section> : <p className="studio-meta">尚无后续作者评估；原记录：{originalStatus}。</p>}
    <details><summary>原使用记录与全部作者评估</summary><p>原使用初记：{originalStatus}。</p><p>{record.result}</p><SourceList sources={[record.report, ...record.sources]} open={onReadSource} />{record.assessments?.map((assessment, index) => <section className="studio-assessment" key={`${assessment.at}:${index}`}><h4>作者评估 {index + 1} · {assessment.status}</h4><p>{assessment.result}</p><SourceList sources={[assessment.report, ...assessment.sources]} open={onReadSource} /></section>)}</details>
  </article>;
}

